func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: x509-pem-bundle <reps>")
		os.Exit(2)
	}
	reps, _ := strconv.Atoi(os.Args[1])
	data := []byte(bundle)
	var sum int64
	for i := 0; i < reps; i++ {
		rest := data
		for {
			var b *pem.Block
			b, rest = pem.Decode(rest)
			if b == nil {
				break
			}
			if b.Type != "CERTIFICATE" {
				continue
			}
			c, err := x509.ParseCertificate(b.Bytes)
			if err != nil {
				panic(err)
			}
			sum += int64(len(c.Raw))
		}
	}
	fmt.Println(sum)
}
